		varnodeTable.setDefaultEditor(typeof(Address), new VarnodeLocationCellEditor(model));
		varnodeTable.setDefaultEditor(typeof(Register), new VarnodeLocationCellEditor(model));
		varnodeTable.setDefaultEditor(typeof(Integer), new VarnodeSizeCellEditor());
		varnodeTable.setDefaultRenderer(typeof(Address), new VarnodeLocationTableCellRenderer());
		varnodeTable.setDefaultRenderer(typeof(Register), new VarnodeLocationTableCellRenderer());
		varnodeTable.getTableHeader().setReorderingAllowed(false);
		varnodeTable.setSurrendersFocusOnKeystroke(true);

		JScrollPane scroll = new JScrollPane(varnodeTable);
		scroll.getAccessibleContext().setAccessibleName("Varnode");
		panel.add(scroll, BorderLayout.CENTER);
		panel.add(buildButtonPanel(), BorderLayout.EAST);
		panel.getAccessibleContext().setAccessibleName("Table");
		return panel;
	}

